{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.store_replen_2_feb2025 as WITH sold_yesterday as ( select sku_group,sum(suborder_quantity) as units_sold_store, branch_code, order_date from snitch_db.maplemonk.STORE_fact_items_offline where order_date = current_date - 1 and sku_group not like \'%CB%\' group by sku_group,branch_code, order_date ), thresholds as ( SELECT * FROM snitch_db.maplemonk.store_bifurcation ), sku_specific_thresholds AS ( Select * from ( SELECT sku_group, branch_code, xs_tsh_high_2, s_tsh_high_2, m_tsh_high_2, l_tsh_high_2, xl_tsh_high_2, xxl_tsh_high_2, xl3_tsh_high_2, xl4_tsh_high_2, xl5_tsh_high_2, xl6_tsh_high_2,xl7_tsh_high_2,xl8_tsh_high_2 , ROW_NUMBER() OVER (PARTITION BY SKU_GROUP,branch_code ORDER BY branch_code) AS rn FROM snitch_db.maplemonk.core_skus) ), store_replen_interim as ( select store_replen_1_feb2025.*, omc.percentage_category, cast(omc.THRESHOLD as integer) as categoryParetoReplenThreshold, CASE WHEN categoryParetoReplenThreshold is null THEN 50 ELSE categoryParetoReplenThreshold END as categoryParetoReplenThresholdNoNull, (CASE WHEN XS_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN XL3_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN XL4_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN XL5_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN XL6_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN XL7_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN XL8_UNITS > 1 THEN 1 ELSE 0 END) + (CASE WHEN NA_UNITS > 1 THEN 1 ELSE 0 END) AS NUM_SIZE_WH_NEW, (CASE WHEN XS_UNITS > 1 AND XS_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN S_UNITS > 1 AND S_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN M_UNITS > 1 AND M_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN L_UNITS > 1 AND L_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN XL_UNITS > 1 AND XL_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_UNITS > 1 AND XXL_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN XL3_UNITS > 1 AND XL3_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN XL4_UNITS > 1 AND XL4_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN XL5_UNITS > 1 AND XL5_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN XL6_UNITS > 1 AND XL6_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN XL7_UNITS > 1 AND XL7_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN XL8_UNITS > 1 AND XL8_UNITS_STORE>0 THEN 1 ELSE 0 END) + (CASE WHEN NA_UNITS > 1 AND NA_UNITS_STORE>0 THEN 1 ELSE 0 END) AS NUM_SAME_SIZES, NUM_SIZE_WH_NEW + NUM_SIZE_AVAILABLE - NUM_SAME_SIZES as SIZE_AFTER_REPLEN, CASE WHEN replen_1 > 0 AND omc.cumulative_share <=categoryParetoReplenThresholdNoNull AND SIZE_AFTER_REPLEN>=3 THEN \'REPLEN\' ELSE \'DONT REPLEN\' END AS REPLEN_FLAG, CASE WHEN NUM_SIZE_AVAILABLE < 3 AND omc.cumulative_share>categoryParetoReplenThresholdNoNull THEN \'OUTWARD\' WHEN (omc.cumulative_share <=categoryParetoReplenThresholdNoNull AND replen_1 =0 and sum_size_ratio_percentage_by_sku_group >categoryParetoReplenThresholdNoNull) THEN \'CANNOT REPLEN\' ELSE REPLEN_FLAG END AS Final_action, CASE WHEN REPLEN_FLAG=\'REPLEN\' THEN 1 ELSE 0 END AS FINAL_ALLOC, omc.percentage_category as sku_offline_pareto, A.\"ROS/Sqft\" as size_1, A.\"CLUSTER\" as cluster_1, cor.sku_group as COR from snitch_db.maplemonk.store_replen_1_feb2025 LEFT JOIN snitch_db.maplemonk.offline_pareto omc ON store_replen_1_feb2025.sku_group = omc.sku_group_final and store_replen_1_feb2025.branch_code = omc.BRANCH_CODE left join snitch_db.maplemonk.master_file a on store_replen_1_feb2025.branch_code = A.\"STORE CODE\" left join snitch_db.maplemonk.core_skus cor on store_replen_1_feb2025.sku_group = cor.sku_group and store_replen_1_feb2025.branch_code = cor.branch_code order by priority,units_on_hand desc ) select sri.*, sy.order_date as yesterday_order_date, thresholds.ONL_CAT_1, thresholds.xs_tsh_low_1, thresholds.s_tsh_low_1, thresholds.m_tsh_low_1, thresholds.l_tsh_low_1, thresholds.xl_tsh_low_1, thresholds.xxl_tsh_low_1, thresholds.xl3_tsh_low_1, thresholds.xl4_tsh_low_1, thresholds.xl5_tsh_low_1, thresholds.xl6_tsh_low_1, thresholds.xl7_tsh_low_1, thresholds.xl8_tsh_low_1, COALESCE(sst.xs_tsh_high_2, thresholds.xs_tsh_high_1) AS xs_tsh_high, COALESCE(sst.s_tsh_high_2, thresholds.s_tsh_high_1) AS s_tsh_high, COALESCE(sst.m_tsh_high_2, thresholds.m_tsh_high_1) AS m_tsh_high, COALESCE(sst.l_tsh_high_2, thresholds.l_tsh_high_1) AS l_tsh_high, COALESCE(sst.xl_tsh_high_2, thresholds.xl_tsh_high_1) AS xl_tsh_high, COALESCE(sst.xxl_tsh_high_2, thresholds.xxl_tsh_high_1) AS xxl_tsh_high, COALESCE(sst.xl3_tsh_high_2, thresholds.xl3_tsh_high_1) AS xl3_tsh_high, COALESCE(sst.xl4_tsh_high_2, thresholds.xl4_tsh_high_1) AS xl4_tsh_high, COALESCE(sst.xl5_tsh_high_2, thresholds.xl5_tsh_high_1) AS xl5_tsh_high, COALESCE(sst.xl6_tsh_high_2, thresholds.xl6_tsh_high_1) AS xl6_tsh_high, COALESCE(sst.xl7_tsh_high_2, thresholds.xl7_tsh_high_1) AS xl7_tsh_high, COALESCE(sst.xl8_tsh_high_2, thresholds.xl8_tsh_high_1) AS xl8_tsh_high, ifnull(CAST(LEFT(percentage_category, LEN(percentage_category) - 1) AS INT),100) as pareto, CASE WHEN sy.units_sold_store IS NULL THEN 0 ELSE sy.units_sold_store END as units_sold_yesterday, CASE WHEN COR IS NOT NULL THEN CASE WHEN sst.xs_tsh_high_2 - XS_UNITS_STORE > 0 THEN sst.xs_tsh_high_2 - XS_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'XS\' THEN replen_1 ELSE 0 END END AS XS_alloc, CASE WHEN COR IS NOT NULL THEN CASE WHEN sst.s_tsh_high_2 - S_UNITS_STORE > 0 THEN sst.s_tsh_high_2 - S_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'S\' THEN replen_1 ELSE 0 END END AS S_alloc, CASE WHEN COR IS NOT NULL THEN CASE WHEN sst.m_tsh_high_2 - M_UNITS_STORE > 0 THEN sst.M_tsh_high_2 - M_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'M\' THEN replen_1 ELSE 0 END END AS M_alloc, CASE WHEN COR IS NOT NULL THEN CASE WHEN sst.l_tsh_high_2 - L_UNITS_STORE > 0 THEN sst.L_tsh_high_2 - L_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'L\' THEN replen_1 ELSE 0 END END AS L_alloc, CASE WHEN COR IS NOT NULL THEN CASE WHEN sst.xl_tsh_high_2 - XL_UNITS_STORE > 0 THEN sst.XL_tsh_high_2 - XL_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'XL\' THEN replen_1 ELSE 0 END END AS XL_alloc, CASE WHEN COR IS NOT NULL THEN CASE WHEN sst.xxl_tsh_high_2 - XXL_UNITS_STORE > 0 THEN sst.XXL_tsh_high_2 - XXL_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'XXL\' THEN replen_1 ELSE 0 END END AS XXL_alloc, CASE WHEN COR IS NOT NULL THEN CASE WHEN sst.xl3_tsh_high_2 - XL3_UNITS_STORE > 0 THEN sst.XL3_tsh_high_2 - XL3_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'3XL\' THEN replen_1 ELSE 0 END END AS XL3_alloc, CASE WHEN COR IS NOT NULL THEN CASE WHEN sst.xl4_tsh_high_2 - XL4_UNITS_STORE > 0 THEN sst.XL4_tsh_high_2 - XL4_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'4XL\' THEN replen_1 ELSE 0 END END AS XL4_alloc, CASE WHEN COR IS NOT NULL THEN CASE WHEN sst.xl5_tsh_high_2 - XL5_UNITS_STORE > 0 THEN sst.XL5_tsh_high_2 - XL5_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'5XL\' THEN replen_1 ELSE 0 END END AS XL5_alloc, CASE WHEN COR IS NOT NULL THEN CASE WHEN sst.xl6_tsh_high_2 - XL6_UNITS_STORE > 0 THEN sst.XL6_tsh_high_2 - XL6_UNITS_STORE ELSE 0 END ELSE CASE WHEN FINAL_ALLOC = 1 AND size_mapped = \'6XL\' THEN replen_1 ELSE 0 END END AS XL6_alloc, CASE WHEN size_mapped = \'NA\' THEN replen_1 ELSE 0 END AS NA_alloc FROM store_replen_interim sri LEFT JOIN sold_yesterday sy ON sri.sku_group=sy.sku_group AND SRI.BRANCH_CODE =SY.BRANCH_CODE LEFT JOIN thresholds ON lower(sri.CLUSTER_1)=lower(thresholds.CLUSTER_1) and lower(sri.size_1)=lower(thresholds.SIZE_1) and lower(sri.availability_category)=lower(thresholds.ONL_CAT_1) LEFT JOIN sku_specific_thresholds sst ON sri.sku_group = sst.sku_group AND sri.branch_code = sst.branch_code ;",
                    "transaction": true
                }
            ) }}
